<?php
/** Plugin Name: TEMP PS S1697 feeds v2.6.0 deploy */
add_action('wp_loaded', function(){
  $f=(isset($_GET['ps_s1697'])?$_GET['ps_s1697']:''); if(!in_array($f,array('1','2','3'),true)) return;
  header('Content-Type: application/json; charset=utf-8');
  $o=array('v'=>'S1697 md','faze'=>$f); $t=WP_CONTENT_DIR.'/plugins/petshop-feeds/petshop-feeds.php';
  $up=wp_upload_dir(); $bak=$up['basedir'].'/ps-backups/petshop-feeds.php.bak_s1697';
  try{
    if($f==='1'){ // deploy
      $src=base64_decode(''); $o['md5_gauta']=md5($src); $o['md5_laukta']='26a2f74d37b8cadcbb2024411d4f2bde';
      if(md5($src)!=='26a2f74d37b8cadcbb2024411d4f2bde') throw new Exception('md5 nesutampa');
      $tok=token_get_all($src,TOKEN_PARSE); $o['tokenu']=count($tok);
      $o['md5_sena']=md5_file($t); if(!copy($t,$bak)) throw new Exception('bak nepavyko');
      if(file_put_contents($t,$src)!==strlen($src)) throw new Exception('rasymas nepavyko');
      if(function_exists('opcache_invalidate')) opcache_invalidate($t,true);
      $r=wp_remote_get(home_url('/?ps_hb='.time()),array('timeout'=>20)); $c=is_wp_error($r)?0:wp_remote_retrieve_response_code($r); $o['heartbeat']=$c;
      if($c>=500||$c===0){ copy($bak,$t); $o['ROLLBACK']=1; }
      $o['md5_nauja']=md5_file($t);
    } elseif($f==='2'){ // generuoti kaina24 + kainos (ne google)
      $o['versija']=PS_FEEDS_VERSIJA; $t0=microtime(true);
      $st=ps_feeds_generuoti(array('kaina24','kainos'),false); $o['stat']=$st; $o['sek']=round(microtime(true)-$t0,1);
    } else { // patikra
      $s=file_get_contents($up['basedir'].'/petshop-feeds/kaina24.xml'); preg_match_all('/<manufacturer><!\[CDATA\[(.*?)\]\]>/s',$s,$m); $b=array_count_values($m[1]); arsort($b);
      $o['k24_manufacturer']=array_slice($b,0,40,true); $o['k24_n']=substr_count($s,'<product id=');
      $s2=file_get_contents($up['basedir'].'/petshop-feeds/kainos.xml'); preg_match_all('/<manufacturer><!\[CDATA\[(.*?)\]\]>/s',$s2,$m2); $b2=array_count_values($m2[1]); $o['kainos_josera']=array_filter($b2,function($k){return stripos($k,'josera')!==false||stripos($k,'excl')!==false||stripos($k,'animonda')!==false;},ARRAY_FILTER_USE_KEY);
      foreach(array('kaina24','kainos','google') as $c){ $r=wp_remote_head(home_url('/feed/'.$c),array('timeout'=>15)); $o['http'][$c]=is_wp_error($r)?'ERR':wp_remote_retrieve_response_code($r); }
      $o['google_mtime']=date('Y-m-d H:i',filemtime($up['basedir'].'/petshop-feeds/google.xml'));
      $o['be_gtin_brendai']=$GLOBALS['wpdb']->get_results("SELECT t.name b, COUNT(*) n FROM {$GLOBALS['wpdb']->prefix}posts po JOIN {$GLOBALS['wpdb']->prefix}postmeta s ON s.post_id=po.ID AND s.meta_key='_stock_status' AND s.meta_value='instock' LEFT JOIN {$GLOBALS['wpdb']->prefix}postmeta g ON g.post_id=po.ID AND g.meta_key='_global_unique_id' AND g.meta_value<>'' LEFT JOIN {$GLOBALS['wpdb']->prefix}term_relationships tr ON tr.object_id=po.ID LEFT JOIN {$GLOBALS['wpdb']->prefix}term_taxonomy tt ON tt.term_taxonomy_id=tr.term_taxonomy_id AND tt.taxonomy='product_brand' LEFT JOIN {$GLOBALS['wpdb']->prefix}terms t ON t.term_id=tt.term_id WHERE po.post_type='product' AND po.post_status='publish' AND g.post_id IS NULL AND (tt.taxonomy='product_brand' OR tt.taxonomy IS NULL) GROUP BY t.name ORDER BY n DESC LIMIT 40",ARRAY_A);
    }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
});
